import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import Confetti from '../Confetti';

// Difficulty configuration with neural-themed colors and effects
const DIFFICULTY_CONFIG = {
  easy: {
    color: '#10B981', // green-500
    glow: 'rgba(16, 185, 129, 0.6)',
    points: 5,
    bgClass: 'bg-green-500/20',
    textClass: 'text-green-300'
  },
  medium: {
    color: '#F59E0B', // amber-500
    glow: 'rgba(245, 158, 11, 0.7)',
    points: 10,
    bgClass: 'bg-amber-500/20',
    textClass: 'text-amber-300'
  },
  hard: {
    color: '#EF4444', // red-500
    glow: 'rgba(239, 68, 68, 0.8)',
    points: 20,
    bgClass: 'bg-red-500/20',
    textClass: 'text-red-300'
  }
};

// Neural nodes for visual effects
const NeuralNode = ({ x, y, size, pulseDelay, color }) => (
  <motion.div
    className="absolute rounded-full pointer-events-none"
    style={{
      left: `${x}%`,
      top: `${y}%`,
      width: `${size}px`,
      height: `${size}px`,
      backgroundColor: color || '#64C8FF',
      filter: 'blur(0.5px)'
    }}
    initial={{ opacity: 0 }}
    animate={{ 
      opacity: [0.3, 0.9, 0.3],
      boxShadow: [
        `0 0 2px ${color}70`,
        `0 0 8px ${color}90`,
        `0 0 2px ${color}70`
      ]
    }}
    transition={{
      duration: 2,
      repeat: Infinity,
      delay: pulseDelay
    }}
  />
);

// Circuit connection between nodes
const CircuitConnection = ({ x1, y1, x2, y2, color, delay }) => {
  // Create a zigzag path for more circuit-like look
  const midX = (x1 + x2) / 2;
  
  return (
    <motion.div 
      className="absolute top-0 left-0 w-full h-full pointer-events-none"
      style={{ zIndex: 0 }}
    >
      <svg width="100%" height="100%" className="absolute inset-0">
        <motion.path
          d={`M ${x1}% ${y1}% L ${midX}% ${y1}% L ${midX}% ${y2}% L ${x2}% ${y2}%`}
          stroke={color || 'rgba(100, 200, 255, 0.5)'}
          strokeWidth="1"
          fill="none"
          strokeDasharray="3,2"
          initial={{ pathLength: 0, opacity: 0 }}
          animate={{ 
            pathLength: [0, 1],
            opacity: [0.3, 0.7, 0.3]
          }}
          transition={{ 
            duration: 2.5, 
            repeat: Infinity,
            repeatType: "reverse",
            delay
          }}
        />
      </svg>
    </motion.div>
  );
};

// Animated checkmark SVG
const AnimatedCheckmark = ({ isChecked, onComplete }) => {
  React.useEffect(() => {
    if (isChecked) {
      const timer = setTimeout(() => {
        if (onComplete) onComplete();
      }, 500); // Wait for animation to complete
      
      return () => clearTimeout(timer);
    }
  }, [isChecked, onComplete]);
  
  return (
    <svg width="24" height="24" viewBox="0 0 24 24" className="text-white">
      <motion.path
        d="M5 13l4 4L19 7"
        fill="transparent"
        strokeWidth="2"
        stroke="currentColor"
        strokeLinecap="round"
        strokeLinejoin="round"
        initial={{ pathLength: 0 }}
        animate={{ pathLength: isChecked ? 1 : 0 }}
        transition={{ duration: 0.5, ease: "easeInOut" }}
      />
    </svg>
  );
};

const NeuralTaskItem = ({ task, onToggle, onDelete, onEdit }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editedTitle, setEditedTitle] = useState(task.title);
  const [showConfetti, setShowConfetti] = useState(false);
  
  const handleCheck = () => {
    if (!task.completed) {
      setShowConfetti(true);
      setTimeout(() => setShowConfetti(false), 2500);
    }
    onToggle(task.id);
  };
  
  const handleEditSubmit = (e) => {
    e.preventDefault();
    if (editedTitle.trim()) {
      onEdit(task.id, { ...task, title: editedTitle });
      setIsEditing(false);
    }
  };
  
  const difficultySettings = DIFFICULTY_CONFIG[task.difficulty];
  
  return (
    <motion.div
      className={`relative p-4 mb-4 rounded-xl backdrop-blur-lg border-2 ${
        task.completed ? 'bg-gray-900/30 border-gray-700/50' : 'bg-gray-900/70 border-neural-400/40'
      }`}
      layout
      initial={{ opacity: 0, y: 20 }}
      animate={{ 
        opacity: 1, 
        y: 0,
        boxShadow: task.completed 
          ? 'none' 
          : `0 0 20px ${difficultySettings.glow}`
      }}
      exit={{ opacity: 0, x: -100 }}
      transition={{ duration: 0.3, type: "spring" }}
      style={{ 
        borderLeft: `4px solid ${difficultySettings.color}`,
      }}
    >
      {showConfetti && <Confetti />}
      
      {/* Grid pattern background */}
      <div className="absolute inset-0 pointer-events-none opacity-10" 
        style={{
          backgroundImage: 'linear-gradient(to right, rgba(100, 200, 255, 0.2) 1px, transparent 1px), linear-gradient(to bottom, rgba(100, 200, 255, 0.2) 1px, transparent 1px)',
          backgroundSize: '15px 15px'
        }}
      />
      
      {/* Neural glow effect for incomplete tasks */}
      {!task.completed && (
        <motion.div 
          className="absolute inset-0 rounded-xl overflow-hidden pointer-events-none"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
        >
          {/* Background glow */}
          <motion.div 
            className="absolute -inset-1 rounded-full"
            style={{ 
              background: `radial-gradient(circle at 50% 50%, ${difficultySettings.color}30, transparent 70%)`,
              opacity: 0.6
            }}
            animate={{ 
              scale: [0.9, 1.1, 0.9],
              opacity: [0.4, 0.7, 0.4]
            }}
            transition={{ duration: 3, repeat: Infinity }}
          />
          
          {/* Horizontal scan line */}
          <motion.div
            className="absolute left-0 right-0 h-px"
            style={{ 
              background: `linear-gradient(to right, transparent, ${difficultySettings.color}, transparent)`,
              top: '50%' 
            }}
            animate={{
              opacity: [0, 0.7, 0],
              top: ['10%', '90%']
            }}
            transition={{
              duration: 4,
              repeat: Infinity,
              repeatType: "reverse"
            }}
          />
          
          {/* Neural nodes inside the task card */}
          {[...Array(4)].map((_, i) => {
            const x = 10 + Math.random() * 80;
            const y = 10 + Math.random() * 80;
            return (
              <NeuralNode 
                key={`task-node-${task.id}-${i}`}
                x={x}
                y={y}
                size={2 + Math.random() * 3}
                pulseDelay={i * 0.5}
                color={difficultySettings.color}
              />
            );
          })}
          
          {/* Circuit connections between nodes */}
          {[...Array(3)].map((_, i) => {
            const x1 = 10 + Math.random() * 40;
            const y1 = 10 + Math.random() * 80;
            const x2 = 60 + Math.random() * 30;
            const y2 = 10 + Math.random() * 80;
            
            return (
              <CircuitConnection
                key={`circuit-${task.id}-${i}`}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                color={`${difficultySettings.color}90`}
                delay={i * 0.3}
              />
            );
          })}
        </motion.div>
      )}
      
      <div className="flex items-center relative z-10">
        <motion.button
          className={`w-7 h-7 mr-3 rounded-full flex items-center justify-center ${
            task.completed 
              ? 'bg-gradient-to-br from-green-400 to-green-600' 
              : 'border-2 border-neural-400 hover:border-neural-200 bg-gray-900/70'
          }`}
          whileHover={{ 
            scale: 1.1, 
            boxShadow: `0 0 10px ${task.completed ? 'rgba(16, 185, 129, 0.8)' : difficultySettings.glow}` 
          }}
          whileTap={{ scale: 0.9 }}
          onClick={handleCheck}
        >
          {task.completed && <AnimatedCheckmark isChecked={task.completed} />}
        </motion.button>
        
        {isEditing ? (
          <form onSubmit={handleEditSubmit} className="flex-grow mr-2">
            <input
              type="text"
              value={editedTitle}
              onChange={(e) => setEditedTitle(e.target.value)}
              className="w-full bg-gray-800/90 text-white px-3 py-1 rounded focus:outline-none focus:ring-2 focus:ring-neural-400/60 border border-neural-400/40"
              autoFocus
              onBlur={handleEditSubmit}
            />
          </form>
        ) : (
          <div className="flex-grow mr-2" onClick={() => setIsEditing(true)}>
            <h3 className={`text-lg font-medium ${task.completed ? 'text-gray-400 line-through' : 'text-white'}`}>
              {task.title}
            </h3>
            <div className="flex items-center mt-1">
              <span className={`text-xs mr-3 font-semibold px-2 py-0.5 rounded-full ${
                difficultySettings.bgClass
              } ${difficultySettings.textClass} border border-${task.difficulty}-500/30`}>
                {task.difficulty.charAt(0).toUpperCase() + task.difficulty.slice(1)}
              </span>
              {task.estimatedTime && (
                <span className="text-xs text-neural-200 flex items-center">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 mr-1" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" />
                  </svg>
                  {task.estimatedTime} min
                </span>
              )}
            </div>
          </div>
        )}
        
        <motion.button
          className="p-2 text-gray-400 hover:text-white rounded-full hover:bg-gray-800/70"
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
          onClick={() => onDelete(task.id)}
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <line x1="18" y1="6" x2="6" y2="18"></line>
            <line x1="6" y1="6" x2="18" y2="18"></line>
          </svg>
        </motion.button>
      </div>
      
      {/* Progress bar for tasks with estimated time */}
      {task.progress !== undefined && task.estimatedTime > 0 && (
        <div className="mt-3">
          <div className="flex justify-between text-xs text-neural-200 mb-1">
            <span>Progress</span>
            <span>{Math.round(task.progress)}%</span>
          </div>
          <div className="h-3 bg-gray-900/70 rounded-full overflow-hidden relative border border-neural-400/20">
            {/* Progress background grid */}
            <div className="absolute inset-0 opacity-20" 
              style={{
                backgroundImage: `linear-gradient(to right, ${difficultySettings.color}20 1px, transparent 1px)`,
                backgroundSize: '5px 5px'
              }}
            />
            
            <motion.div
              className="h-full absolute left-0 top-0"
              style={{
                background: `linear-gradient(90deg, ${difficultySettings.color}90, ${difficultySettings.color})`
              }}
              initial={{ width: 0 }}
              animate={{ width: `${task.progress}%` }}
              transition={{ duration: 0.5, ease: "easeOut" }}
            />
            
            {/* Progress edge glow */}
            <motion.div
              className="absolute top-0 bottom-0 w-3"
              style={{
                left: `calc(${task.progress}% - 3px)`,
                background: `linear-gradient(to right, transparent, ${difficultySettings.color})`
              }}
              animate={{
                opacity: [0.5, 0.9, 0.5]
              }}
              transition={{
                duration: 1.5,
                repeat: Infinity
              }}
            />
            
            {/* Neural nodes along the progress bar */}
            {[...Array(5)].map((_, i) => {
              const position = Math.min(10 + (i * 20), task.progress);
              return position <= task.progress && (
                <motion.div
                  key={`progress-node-${task.id}-${i}`}
                  className="absolute top-1/2 rounded-full bg-white"
                  style={{
                    width: 4,
                    height: 4,
                    left: `${position}%`,
                    transform: 'translate(-50%, -50%)',
                    zIndex: 20
                  }}
                  animate={{
                    boxShadow: [
                      `0 0 2px ${difficultySettings.color}`,
                      `0 0 8px ${difficultySettings.color}`,
                      `0 0 2px ${difficultySettings.color}`
                    ]
                  }}
                  transition={{ duration: 1.2, repeat: Infinity }}
                />
              );
            })}
          </div>
        </div>
      )}
    </motion.div>
  );
};

export default NeuralTaskItem; 