import React, { useMemo } from 'react';
import { motion } from 'framer-motion';
import NeuralPageWrapper from '../components/NeuralPageWrapper';
import NeuralTaskList from '../components/neural/NeuralTaskList';
import { useAuth } from '../contexts/AuthContext';

// Neural node component for visual effects
const NeuralNode = ({ x, y, size, pulseDelay, color }) => (
  <motion.div
    className="absolute rounded-full pointer-events-none"
    style={{
      left: `${x}%`,
      top: `${y}%`,
      width: `${size}px`,
      height: `${size}px`,
      backgroundColor: color || '#64C8FF',
      filter: 'blur(1px)'
    }}
    initial={{ opacity: 0 }}
    animate={{
      opacity: [0.2, 0.7, 0.2],
      boxShadow: [
        '0 0 2px rgba(100, 200, 255, 0.3)',
        '0 0 8px rgba(100, 200, 255, 0.6)',
        '0 0 2px rgba(100, 200, 255, 0.3)'
      ]
    }}
    transition={{
      duration: 2.5,
      repeat: Infinity,
      delay: pulseDelay
    }}
  />
);

const Tasks = () => {
  const { currentUser } = useAuth();
  
  // Get tasks from the authenticated user with safety checks
  const tasks = useMemo(() => {
    if (currentUser && Array.isArray(currentUser.tasks)) {
      return currentUser.tasks;
    }
    return [];
  }, [currentUser]);
  
  // Item transition variant
  const itemVariants = {
    initial: { opacity: 0, y: 20 },
    animate: { 
      opacity: 1,
      y: 0,
      transition: { 
        type: "spring",
        stiffness: 300,
        damping: 25
      } 
    },
  };

  // Generate neural nodes for the background
  const nodes = useMemo(() => {
    const nodeArray = [];
    for (let i = 0; i < 20; i++) {
      nodeArray.push({
        x: Math.random() * 100,
        y: Math.random() * 100,
        size: 2 + Math.random() * 3,
        pulseDelay: Math.random() * 2
      });
    }
    return nodeArray;
  }, []);

  return (
    <NeuralPageWrapper
      title="Neural Task Network"
      subtitle="Organize your study tasks and connect neural pathways to success"
    >
      <div className="relative">
        {/* Neural Background Effect */}
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
          <motion.div
            className="absolute inset-0"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 1.5 }}
          >
            <svg className="w-full h-full opacity-10">
              <defs>
                <linearGradient id="neural-task-gradient" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#3B82F6" stopOpacity="0.6" />
                  <stop offset="100%" stopColor="#64C8FF" stopOpacity="0.6" />
                </linearGradient>
              </defs>
              <motion.g
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                transition={{ duration: 1, delay: 0.5 }}
              >
                {Array.from({ length: 10 }).map((_, i) => (
                  <motion.path
                    key={`neural-path-${i}`}
                    d={`M${Math.random() * 100},${Math.random() * 100} Q${Math.random() * 100},${Math.random() * 100} ${Math.random() * 100},${Math.random() * 100}`}
                    stroke="url(#neural-task-gradient)"
                    strokeWidth="0.5"
                    fill="none"
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ pathLength: 1, opacity: 0.5 }}
                    transition={{ duration: 2, delay: i * 0.1 }}
                  />
                ))}
              </motion.g>
            </svg>
          </motion.div>

          {/* Background neural nodes */}
          {nodes.map((node, i) => (
            <NeuralNode 
              key={`bg-node-${i}`}
              x={node.x}
              y={node.y}
              size={node.size}
              pulseDelay={node.pulseDelay}
              color="rgba(100, 200, 255, 0.4)"
            />
          ))}

          {/* Scan line effect */}
          <motion.div
            className="absolute h-0.5 w-full left-0"
            style={{
              background: 'linear-gradient(90deg, transparent, rgba(100, 200, 255, 0.5), transparent)',
              top: '0%'
            }}
            animate={{
              top: ['0%', '100%']
            }}
            transition={{
              duration: 8,
              repeat: Infinity,
              ease: "linear"
            }}
          />
        </div>
        
        <motion.div
          className="glass-panel rounded-xl overflow-hidden border border-neural-400/20 shadow-neural relative z-10"
          variants={itemVariants}
          initial="initial"
          animate="animate"
        >
          <motion.div 
            className="absolute top-0 left-0 w-full h-px"
            style={{
              background: 'linear-gradient(90deg, transparent, rgba(100, 200, 255, 0.5), transparent)'
            }}
            animate={{
              opacity: [0.2, 0.8, 0.2],
              width: ['0%', '100%', '0%']
            }}
            transition={{ duration: 4, repeat: Infinity }}
          />

          <div className="p-6">
            <NeuralTaskList initialTasks={tasks} />
          </div>
        </motion.div>
      </div>
    </NeuralPageWrapper>
  );
};

export default Tasks; 